export const subValue = (fs: number, name: string): number => FLIGHT_SUB[fs].indexOf(name)
/** Swarm-wide red highlight: CORRECTING <= fs <= CRASHED and fs != LANDED, or ALERT (g04 §5.4). */
export const redHighlight = (fs: number, flags: number): boolean =>
  (fs >= FlightState.CORRECTING && fs <= FlightState.CRASHED && fs !== FlightState.LANDED) || (flags & FlightFlags.ALERT) !== 0
